$message=null;$error='';
if ($_SERVER['REQUEST_METHOD']==='POST') {
    app_check_csrf();family_child($children,(int)app_value($_POST,'child'));$childId=(int)$_POST['child'];
    $text=trim((string)app_value($_POST,'text'));$subject=trim((string)app_value($_POST,'subject'));
    $destination=(int)app_value($_POST,'destination',0)===1?1:0;
    if(app_value($_POST,'action')==='read'){
        $readMessage=family_message((int)app_value($_POST,'message'),$parent);
        app_db()->set_charset('utf8mb4');
        db_query_params('UPDATE agenda_notas_padres SET estado=1 WHERE id_nota_padre=? AND tipo_nota=2 AND COALESCE(estado,0)=0','i',[(int)$readMessage['id_nota_padre']],app_db());
        db_query_params('UPDATE agenda_notas_padres_respuestas SET leida=1 WHERE id_nota=? AND direccion=1','i',[(int)$readMessage['id_nota_padre']],app_db());
        header('Location: /app/?view=mensajes&child='.(int)$readMessage['id_alumno'].'&message='.(int)$readMessage['id_nota_padre'],true,303);exit;
    }
    if ($text==='' || mb_strlen($text)>12000 || mb_strlen($subject)>150 || !preg_match('//u',$text.$subject)) $error='Escribe un mensaje de hasta 12.000 caracteres y un asunto de hasta 150.';
    else {
        app_db()->set_charset('utf8mb4');
        if (app_value($_POST,'action')==='reply') {
            $message=family_message((int)app_value($_POST,'message'),$parent);
            $childId=(int)$message['id_alumno'];
            $text=htmlspecialchars($text,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');
            $ok=db_query_params('INSERT INTO agenda_notas_padres_respuestas (id_nota,respondido_por,fecha_respuesta,hora_respuesta,texto_respuesta,leida,direccion) VALUES (?,?,CURDATE(),CURTIME(),?,0,0)','iis',array((int)$message['id_nota_padre'],$parent,$text),app_db());
        } else {
            if ($subject==='') $subject='Consulta de la familia';
            $ok=db_query_params('INSERT INTO agenda_notas_padres (id_padre,id_alumno,id_remitente,tipo_nota,asunto,texto_nota,fecha,hora,destino,estado) VALUES (?,?,?,0,?,?,CURDATE(),CURTIME(),?,0)','iiissi',array($parent,$childId,$parent,$subject,htmlspecialchars($text,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8'),$destination),app_db());
        }
        if ($ok) { $_SESSION['family_notice']='Mensaje enviado a la piscina.';header('Location: /app/?view=mensajes&child='.$childId,true,303);exit; }
        $error='No se ha podido guardar el mensaje. Vuelve a intentarlo.';
    }
}
app_db()->set_charset('utf8mb4');
