$active=array();foreach($enrolments as $e) if ($e['curso_inicio']<=date('Y-m-d') && $e['curso_fin']>=date('Y-m-d') && ($e['fecha_baja']==='0000-00-00' || !$e['fecha_baja'] || $e['fecha_baja']>=date('Y-m-d'))) $active[]=$e;
