function family_money($n){return number_format((float)$n,2,',','.').' €';}
function family_total($lines){$sum=0;foreach($lines as $l)$sum+=(float)$l['cantidad']*(float)$l['precio']*(1-round((float)$l['dto']/100,2))*(1+(float)$l['tipo_iva']);return round($sum,2);}
function family_date($date){return $date && $date!=='0000-00-00'?date('d/m/Y',strtotime($date)):'';}
